    country_stats = (
        cust_country.groupby('Country')
        .agg(
            total_customers=('CustomerID', 'nunique'),
            repeat_customers=('is_repeat', 'sum')
        )
        .reset_index()
    )
    country_stats['repeat_rate'] = country_stats['repeat_customers'] / country_stats['total_customers']

